parameters.jsCode:
const results = [];

for (const item of $input.all()) {
  let source = 'CHAT';
  let text = '';

  try {
    const emailItem = $('Recibir Ticket (Email)').item;
    source = 'EMAIL';
    text = emailItem.json.text || emailItem.json.snippet || '';
  } catch (error) {
    const chatItem = $('When chat message received').item;
    text = chatItem.json.chatInput || '';
  }

  const clasificacion = item.json.output;

  results.push({
    json: {
      source,
      text,
      category: clasificacion.category,
      severity: clasificacion.severity,
      draftResponse: clasificacion.draftResponse,
      reasoning: clasificacion.reasoning
    }
  });
}

return results;

