const results = [];

const teamByCategory = {
  'Facturación': 'Finanzas',
  'Acceso y Cuentas': 'Identity',
  'Rendimiento': 'Plataforma',
  'Integraciones': 'Integraciones',
  'Datos y reportes': 'Datos',
  'Interfaz / uso': 'Producto',
  'Fuera de alcance': 'Ninguno (redirigir)'
};

const slaBySeverity = {
  'Crítica': { responseTarget: '1 hora', resolutionTarget: '4 horas', responseHours: 1, resolutionHours: 4 },
  'Alta': { responseTarget: '4 horas', resolutionTarget: '24 horas', responseHours: 4, resolutionHours: 24 },
  'Media': { responseTarget: '8 horas', resolutionTarget: '72 horas', responseHours: 8, resolutionHours: 72 },
  'Baja': { responseTarget: '24 horas', resolutionTarget: '10 días hábiles', responseHours: 24, resolutionHours: 240 },
  'Fuera de alcance': { responseTarget: 'Redirigir', resolutionTarget: 'No aplica', responseHours: null, resolutionHours: null }
};

function simpleId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

for (const item of $input.all()) {
  const { source, text, category, severity, draftResponse } = item.json;

  const team = teamByCategory[category] || 'Sin asignar';
  const sla = slaBySeverity[severity] || slaBySeverity['Fuera de alcance'];

  const now = new Date();
  const receivedAt = now.toISOString();
  const createdAt = new Date(now.getTime() + 500).toISOString();

  const responseDeadline = sla.responseHours != null
    ? new Date(now.getTime() + sla.responseHours * 3600000).toISOString()
    : null;
  const resolutionDeadline = sla.resolutionHours != null
    ? new Date(now.getTime() + sla.resolutionHours * 3600000).toISOString()
    : null;

  results.push({
    json: {
      id: simpleId(),
      source,
      externalId: `n8n-exec-${$execution.id}`,
      text,
      category,
      severity,
      team,
      sla: {
        responseTarget: sla.responseTarget,
        resolutionTarget: sla.resolutionTarget,
        responseDeadline,
        resolutionDeadline
      },
      draftResponse,
      receivedAt,
      createdAt,
      simulated: true
    }
  });
}

return results;
